From the celebrated Bishop-Gromov Volume Comparison Theorem,  it is well-known that for any complete non-compact Riemannian manifold $(M^n, g)$ with Ricci curvature $Rc\geq 0$, the $n$-dim \textbf{asymptotic volume growth ratio} of $M^n$, denoted as\begin{align}
\mathrm{V}_{M^n, n}\vcentcolon= \lim_{r\rightarrow\infty}\frac{V(B_p(r))}{\omega_n r^n}, \nonumber 
\end{align}
is well-defined and is independent of the choice of $p$; where $B_p(r)$ is the open geodesic ball centered at $p\in M^n$ with radius $r> 0$,  $V(B_p(r))$ is the volume of $B_p(r)$,  and $\omega_n$ is the volume of unit ball in $\mathbb{R}^n$.

\begin{align}
\mathrm{V}_{M^n, n}\vcentcolon= \lim_{r\rightarrow\infty}\frac{V(B_p(r))}{\omega_n r^n}, \nonumber 
\end{align}

{There is a universal constant $C(n)> 0$,  such that if $(M^n,  g)$ has $Rc\geq 0$ and the scalar curvature $R\geq 2$, then 
\begin{align}
\sup_{p\in M^n\atop r> 0} \frac{V(B_p(r))}{r^{n- 2}}\leq C(n).  \nonumber 
\end{align}
}

\begin{align}
\sup_{p\in M^n\atop r> 0} \frac{V(B_p(r))}{r^{n- 2}}\leq C(n).  \nonumber 
\end{align}

\label{rem sectional curv is non-nega}
{Note Gromov \cite[2.B.]{Gromov-large-mflds} also sketched a proof of the following result: If $(M^n, g)$ has the sectional curvature $K\geq 0$ and the scalar curvature $R\geq 1$,  then there exists some $C(n)> 0$ such that $\displaystyle V(B_p(r))\leq C(n)\cdot r^{n- 2}$.  
}

\label{conj volume growth of Gromov}
