Motivated to get a generalization of the Cohn-Vossen's inequality in higher dimension,  Yau has posed the following question \cite[Problem 9]{Yau}: For any complete Riemannian manifold $(M^n, g)$ with $Rc\geq 0$, and for any $p\in M^n$, is it true that 
\begin{align}
\lim\limits_{r\rightarrow \infty} \frac{\int_{B_p(r)}R}{r^{n- 2}} < \infty ? \nonumber 
\end{align}

\begin{align}
\lim\limits_{r\rightarrow \infty} \frac{\int_{B_p(r)}R}{r^{n- 2}} < \infty ? \nonumber 
\end{align}

Similar to the concept of asymptotic volume ratio,  for complete  non-compact Riemannian manifolds $(M^n, g)$ with $n\geq 3$, we define the \textbf{$(n-2)$-dim asymptotic volume growth ratio of $M^n$} as follows:
\begin{align}
\mathrm{V}_{M^n, n- 2}\vcentcolon= \varlimsup\limits_{r\rightarrow\infty}\frac{V(B_p(r))}{\omega_{n- 2}r^{n- 2}},  \quad \quad \quad \forall p\in M^n.  \nonumber 
\end{align}

\begin{align}
\mathrm{V}_{M^n, n- 2}\vcentcolon= \varlimsup\limits_{r\rightarrow\infty}\frac{V(B_p(r))}{\omega_{n- 2}r^{n- 2}},  \quad \quad \quad \forall p\in M^n.  \nonumber 
\end{align}

\label{thm main-1 }
{For any complete non-compact Riemannian manifold $(M^3, g)$ with $Rc\geq 0$ and $R\geq 2$, 
\begin{enumerate}
\item[(1)].  if $(M^3, g)$ has only one end,  then $\displaystyle 0< \mathrm{V}_{M^3, 1}\leq 2\pi$,
\item[(2)]. if $(M^3,g)$ has at least two ends, then $(M^3,g)$ is isometric to a cylinder $S\times\mathbb{R}$ with $S$ being a closed surface of sectional curvature at least one, and $\displaystyle 0< \mathrm{V}_{M^3, 1}\leq 4\pi$. 
\item[(3)].  moreover $\mathrm{V}_{M^3, 1}= 4\pi$ if and only if $(M^3,g)$ is isometric to the cylinder $\mathbb{S}^2\times\mathbb{R}$,  where $\mathbb{S}^2$ is the unit round sphere in $\mathbb{R}^3$.
\end{enumerate}
}

\label{rem uniqueness of rigidity}
{Meanwhile,  for any $0<b<1$,  we construct distinct noncompact manifolds $(M_i^3,g_i)$ with  $Rc\geq 0$ and $R\geq 2$,  where $i=1, 2$,  such that   $\displaystyle \mathrm{V}_{M_i^3, 1}=4\pi b$. See Remark \ref{rem two end models} and Remark \ref{rem one end models} for details.

}

\label{rem key observations}
{There are two key observations in this paper: 
\begin{enumerate}
\item[(A)].  The area of $\mu$-bubble surfaces is bounded by the area of unit round sphere $\mathbb{S}^2$,  as $L\rightarrow \infty$.  This bound is sharp in asymptotic sense,  where asymptotic means $L\rightarrow \infty$.
\item[(B)].  The area of the intersection of geodesic spheres with the neighborhood of the ray,  has an upper bound in term of the area bound of corresponding $\mu$-bubble surfaces.
\end{enumerate}
}

\label{notation Ek and Nk}
{For a complete Riemannian manifold $(M^n, g)$ and $L> 0$,  if $(M^n, g)$ has only one end,  the unique unbounded connected component of $M^n- \overline{B_p(kL)}$ is denote by $E_k(p, L)$ . And when the context is clear (or $p, L$ are fixed), we use $E_k$ to denote $E_k(p, L)$ for simplicity. Furthermore, we define $N_k\vcentcolon= E_k- \overline{E_{k+ 1}}$. 
}

\label{rem key points}
{Another key point is: all estimates (including some `height' estimates of cylindrical region) related to area or volume obtained in this paper are asymptotically sharp with respect to $L\rightarrow \infty$.
}

\label{def bubble and bubble surface}
{Assume $N$ is a smooth Riemannian manifold with boundary $\partial N= \partial_{-}N\cup \partial_{+}N$, where $\partial_{-}N\cap \partial_{+}N= \emptyset$ and $\partial_{\pm}N\neq \emptyset$. Fix a smooth function $u> 0$ on $N$ and a smooth function $h$ on $\mathring{N}$ with $h\rightarrow \pm \infty$ on $\partial_{\pm}N$, where $\mathring{N}$ is the interior of $N$. Choose a Caccioppoli set $\mathcal{C}\subseteq N$ such that
\begin{align}
\partial \mathcal{C}- \partial_+ N \ \text{is smooth},\quad \quad \partial \mathcal{C}- \partial_+ N\subseteq \mathring{N}\quad \quad \text{and} \quad \quad \partial_+ N\subseteq \partial \mathcal{C}. \label{assumption on Cacci set C}
\end{align}
Define $\mathscr{C}(N, \mathcal{C})$ as the set of all Caccioppoli sets $\Omega\subseteq N$ with $\Omega\triangle \mathcal{C}\subseteq \mathring{N}$.

We define $\mathcal{A}: \mathscr{C}(N, \mathcal{C})\rightarrow \mathbb{R}$ as follows:
\begin{align}
\mathcal{A}(W)= \int_{ \partial^* W- \partial N}u d\mathcal{H}^{n-1}- \int_N (\chi_W- \chi_{\mathcal{C}})\cdot h\cdot ud\mathcal{H}^{n},\quad \quad \quad \forall W\in \mathscr{C}(N, \mathcal{C}),\nonumber 
\end{align}
where $\partial^* W$ is the reduced boundary of $W$. 

 If $\displaystyle \mathcal{A}(\Omega)= \inf_{W\in \mathscr{C}(N, \mathcal{C})}\mathcal{A}(W)$ for some $\Omega\in \mathscr{C}(N, \mathcal{C})$, we call $\Omega$ as a \textbf{$\mu$-bubble with respect to $(h, u, \mathcal{C})$ in $(N, \partial_{-}N, \partial_{+}N)$} (See Figure \ref{figure: bubble-surface}). 

For any $\mu$-bubble $\Omega$ with respect to $(h, u, \mathcal{C})$ in $(N, \partial_{-}N, \partial_{+}N)$, we call any connected component of $\partial\Omega- \partial N$ as a \textbf{$\mu$-bubble hypersurface with respect to $(h, u, \mathcal{C})$ in $(N, \partial_{-}N, \partial_{+}N)$}. When $\partial\Omega- \partial N$ is two dimensional, we also call its connected components as $\mu$-bubble surfaces.
}

\begin{align}
\partial \mathcal{C}- \partial_+ N \ \text{is smooth},\quad \quad \partial \mathcal{C}- \partial_+ N\subseteq \mathring{N}\quad \quad \text{and} \quad \quad \partial_+ N\subseteq \partial \mathcal{C}. \label{assumption on Cacci set C}
\end{align}

\begin{align}
\mathcal{A}(W)= \int_{ \partial^* W- \partial N}u d\mathcal{H}^{n-1}- \int_N (\chi_W- \chi_{\mathcal{C}})\cdot h\cdot ud\mathcal{H}^{n},\quad \quad \quad \forall W\in \mathscr{C}(N, \mathcal{C}),\nonumber 
\end{align}

\label{prop existence of bubbles}
{There is a $\mu$-bubble $\Omega$ with respect to $(h, u, \mathcal{C})$ in $(N, \partial_{-}N, \partial_{+}N)$, and any $\mu$-bubble hypersurface corresponding to $\Omega$ is a smooth hypersurface.
}

