{\textbf{Step (1)}. Assume $\mathrm{Diam}(\Sigma)= d_g(p, q)$, where $p, q\in \Sigma$. Define $I[\gamma]$ by 
\begin{align}
I[\gamma]= \int_\gamma u ds, \nonumber 
\end{align}
where $ds$ is arclength along $\gamma$ and $\gamma$ is any curves from $p$ to $q$. Let $\gamma_0$ be one minimizer of $I[\cdot]$. 

As in the proof of \cite[Proposition $1$]{SY-CMP} (also see \cite[Proposition $2.2$]{LZ}), let $V(s)= f(s)\cdot v(s)$ be the variation vector field along $\gamma(s)$, where $v(s)$ is the unit normal vector field along $\gamma$. The first variation formula yields
\begin{align}
 u(\gamma_0(s))\nabla_{\partial s}\partial s- (\nabla u)^\perp= 0, \quad \text{along}\ \ \gamma_0.\label{mean curv vanish}
\end{align}

The non-negativity of the  second variation of $I$ at $\gamma_0$ gives
\begin{align}
0\leq \delta^2I[\gamma_0]= \int_{\gamma_0} [D^2u(v, v)- 2u\cdot H^2]\cdot f^2+ u\cdot (|f'|^2- K_\Sigma\cdot f^2)ds, \label{2nd vari non-negat}
\end{align}
where $H$ is the mean curvature of $\gamma\subseteq \Sigma$.  

Note $\displaystyle \Delta_\Sigma u= D^2u(v, v)+ D^2u(\partial s, \partial s)$, combining (\ref{mean curv vanish}), we get
\begin{align}
\Delta_\Sigma u&= D^2u(v, v)+ D^2u(\partial s, \partial s)= D^2u(v, v)+ u''- \nabla_{\nabla_{\partial s}\partial s}u \nonumber \\
&= D^2u(v, v)+ u''- H^2\cdot u, \label{Hessian of u}
\end{align}
where  $u'\vcentcolon= \frac{d}{d s}u(\gamma_0(s))$.

Plugging (\ref{Hessian of u}) into (\ref{2nd vari non-negat}), using the equation of $u$ in the assumption, we obtain
\begin{align}
0&\leq \int_{\gamma_0} [\Delta_\Sigma u- u''(s)- u\cdot H^2]\cdot f^2+ u\cdot (|f'|^2- K_\Sigma\cdot f^2)ds\nonumber \\
&\leq \int_{\gamma_0} - u''(s)\cdot f^2+ u\cdot (|f'|^2- K f^2)ds. \nonumber 
\end{align}

Assume $l= \mathrm{length}(\gamma_0)$,  then integration by parts yields
\begin{align}
\int_0^l u(f')^2+ 2fu'f'- Kuf^2 ds\geq 0, \quad \quad \forall f\in C_0^\infty[0, l]. \label{integ ineq-main}
\end{align}

\textbf{Step (2)}. Put $f(s)= u^{-\frac{1}{2}}(\gamma_0(s))\sin(\frac{\pi}{l}s)$ into (\ref{integ ineq-main}), we get
\begin{align}
&\quad \int_0^l -\frac{3}{4}[(\ln u)']^2 \sin^2(\frac{\pi}{l}s)+ \frac{\pi}{l}(\ln u)'\sin(\frac{\pi}{l}s)\cdot \cos(\frac{\pi}{l}s) ds \nonumber \\
&\geq \int_0^l \left(K\sin^2(\frac{\pi}{l}s)- (\frac{\pi}{l})^2 \cos^2(\frac{\pi}{l}s)\right) ds. \label{integ ineq-intermediate}
\end{align}

By Cauchy-Schwarz inequality, we have
\begin{align}
-\frac{3}{4}[(\ln u)']^2 \sin^2(\frac{\pi}{l}s)+ \frac{\pi}{l}(\ln u)'\sin(\frac{\pi}{l}s)\cdot \cos(\frac{\pi}{l}s) \leq \frac{1}{3}\cdot (\frac{\pi}{l})^2\cos^2(\frac{\pi}{l}s). \label{CS-ineq}
\end{align}

Plugging (\ref{CS-ineq}) into (\ref{integ ineq-intermediate}), we obtain
\begin{align}
\frac{4}{3}\cdot (\frac{\pi}{l})^2\int_0^l\cos^2(\frac{\pi}{l}s) ds\geq K\int_0^l \sin^2(\frac{\pi}{l}s) ds. \nonumber 
\end{align}
This implies $l\leq \frac{2\pi}{\sqrt{3K}}$. 
}
\qed

