\label{def seperating property}
{If a smooth compact hypersurface $\Sigma_k\subseteq E_k- \overline{E_{k+ 1}}$ satisfies the following property: ``for any continuous curve $\gamma: [0, 1]\rightarrow \overline{E_k}- E_{k+ 1}$ with $\gamma(0)\in \partial E_k, \gamma(1)\in \partial E_{k+ 1}$, we have $\gamma\cap \Sigma_k\neq \emptyset$", then we say that \textbf{$\Sigma_k$ separates $\partial E_k$ from $\partial E_{k+ 1}$}. 
}

\label{prop connected property of annulus}
{If $(M^n,  g)$ is a complete Riemannian manifold with only one end and is simply connected,  then there is $k_0\in \mathbb{Z}^+$, such that $\overline{E_k}- E_{k+ 1}$ and $\partial E_k$ are both connected for $k\geq k_0$. 
}

\label{prop volume of separating bubble surfaces}
{Assume $(M^3, g)$ is a complete non-compact Riemannian manifold with $R\geq 2$ and only one end, also it is simply connected and $p\in M^3$.  For any $\varepsilon>0$ and $L> \sqrt{2}\pi(1+\varepsilon)$, there is $k_0= k_0(\varepsilon, L)\in \mathbb{Z}^+$; such that for any $k\geq k_0$, one can find a smooth compact surface $\Sigma_k\subseteq E_k- \overline{E_{k+ 1}}$, which satisfies
\begin{enumerate}
\item[(1)]. $\Sigma_k$ separates $\partial E_k$ from $\partial E_{k+ 1}$;
\item[(2)]. $\displaystyle V(\Sigma_k)\leq \frac{4\pi}{1- \frac{2\pi^2(1+\varepsilon)^2}{L^2}}$. 
\item[(3)]. $\mathrm{Diam}(\Sigma_k)\leq \frac{2\pi}{\sqrt{3(1- \frac{2\pi^2(1+ \varepsilon)^2}{L^2})}}$.
\end{enumerate}
}

\label{rem separate}
{The separating property of suitable $\mu$-bubble surface $\Sigma_k$ (the property (1) above) was firstly observed in the argument of \cite[Lemma $5.4$]{CLS-0}, which is used for our later argument of Lemma \ref{lem surface area comparison}. 
}

~
{\textbf{Step (1)}. It is obvious that $E_{k+ 1}\subseteq E_k$. Recall $N_k= E_k- \overline{E_{k+ 1}}$, and $\partial_+N_k= \partial E_k, \partial_-N_k= \partial E_{k+ 1}$. Then $\partial N_k= \partial_- N_k\sqcup \partial_+ N_k$. From Lemma \ref{lem function for Caccioppoli set}, we can choose a smooth function $f\in C^\infty(M^3)$ with 
\begin{align}
f\big|_{\partial E_k}\leq kL, \quad f\big|_{\partial E_{k+ 1}}> (k+ \frac{1}{2})L, \quad  \text{and} \ (k+ \frac{1}{2})L\ \text{is a regular value of} \ f. \nonumber 
\end{align}
Define $\mathcal{C}_k= \{x\in M^3: f(x)< (k+ \frac{1}{2})L\}\cap N_k$. Then $\mathcal{C}_k$ is a Caccioppoli set satisfying (\ref{assumption on Cacci set C}). 



From Lemma \ref{lem existence of smooth function} there is a function $\rho_k(x):\overline{N_k}\to [-L/2,L/2]$, which is continuous on $\overline{N_k}$ and smooth on $N_k$. Moreover $\rho_k(N_k)\subset(-L/2,L/2)$, and
\begin{align*}
    \rho_k|_{\partial E_k} = -L/2, \quad \rho_k|_{\partial E_{k+1}} = L/2, \quad |\nabla_M \rho_k|<(1+\varepsilon)^2.
\end{align*}

Now choose $h_k(x)= -\frac{2\pi(1+\varepsilon)}{L}\tan(\frac{\pi}{L}\rho_k(x))$ on $N_k$, from Proposition \ref{prop existence of bubbles}, there exists one $\mu$-bubble $\Omega_k$ with respect to $(h_k, 1, \mathcal{C}_k)$ in $(N_k, \partial_{-}N_k, \partial_{+}N_k)$. 

The choice of $h_k$ implies
\begin{align}
\frac{2\pi^2(1+\varepsilon)^2}{L^2}+ \frac{1}{2}h_k^2- |\nabla_M h_k|\geq 0. \label{ineq of h-1}
\end{align}

\textbf{Step (2)}. From Proposition \ref{prop connected property of annulus} and the assumption, there is $k_0\in \mathbb{Z}^+$, such that the sets $\overline{E_k}- E_{k+ 1}, \partial E_k$ are connected for any $k\geq k_0$. In the rest argument, we assume $k\geq k_0$.

Then there is a simple curve $\gamma:[0,1]\to\overline{E_k}- E_{k+ 1}$, with $\gamma(0)=q_1\in\partial E_k$, $\gamma(1)=q_2\in\partial E_{k+1}$ and $\gamma((0,1))\cap (\partial E_k\cup\partial E_{k+1}) =\varnothing$. Furthermore, form the density of transverse intersections, we may assume $\gamma$ intersects $\Omega_k$ and $\partial \Omega_k$ transversely. 

Let $I_2(\gamma, \partial \Omega_k)$ be the mod 2 intersection number of $\gamma$ and $\partial \Omega_k$. From the transversality, $\gamma\cap \Omega_k$ is an 1-dimensional manifold, which turns out to be a union of closed intervals. So $\displaystyle \#\partial \Big(\gamma\cap \Omega_k\Big) = 0 \mod 2$.  And then
\begin{align*}
    I_2(\gamma, \partial \Omega_k)= \#\gamma\cap \big(\partial \Omega_k\big) = \#\partial \Big(\gamma\cap\Omega_k\Big) = 0 \mod 2.
\end{align*}

From the definition of $\Omega_k$, we know $\partial E_k\subset \Omega_k$. Let $\displaystyle \partial\Omega_k-\partial E_k=\bigcup_i \Sigma_k^i$ be the disjoint union of connected components.  Since $\gamma\cap(\partial E_k)=\{q_1\}$, we get
\begin{align*}
     \sum_i I_2(\gamma,\Sigma_k^i) = \#\gamma\cap \big(\partial \Omega_k\big)-\#\gamma\cap (\partial E_k) = 1\mod 2.
\end{align*}

So there is $i_0$ such that
\begin{align*}
    I_2(\gamma,\Sigma_k^{i_0})=1.
\end{align*}
From the definition of $\Omega_k$, we know $\Omega_k\cap\partial E_{k+1}=\varnothing$. Thus $\Sigma_k^{i_0}\cap \partial E_{k+1}=\varnothing$. And we also have $\Sigma_k^{i_0}\cap \partial E_k=\varnothing$ from the definition.

\textbf{Step (3)}. We use $\Sigma_k$ to denote $\Sigma_k^{i_0}$, then $\Sigma_k$ satisfies the conclusion (1). If not, then there is a simple curve $\check{\gamma}:[0,1]\to\overline{E_k}- E_{k+ 1}$, such that $\check{\gamma}(0)=q_3\in\partial E_{k+1}$, $\check{\gamma}(1)=q_4\in\partial E_k$ and $\check{\gamma}((0,1))\cap (\partial E_k\cup\partial E_{k+1}) =\varnothing$. Moreover
\begin{align*}
    \check{\gamma}([0,1])\cap \Sigma_k=\varnothing.
\end{align*}
Since $\partial E_k$ and $\partial E_{k+1}$ are connected, there are two simple curves $\gamma_1:[0,1]\to\partial E_k$ and $\gamma_2:[0,1]\to\partial E_{k+1}$, such that $\gamma_1(0)=q_4$, $\gamma_1(1)=q_1$, $\gamma_2(0)=q_2$, $\gamma_2(1)=q_3$. Let $\tilde\gamma=\gamma*\gamma_2*\check{\gamma}*\gamma_1$ (see Figure \ref{figure: circle curve}), then
\begin{align}
   I_2(\tilde\gamma,\Sigma_k) = I_2(\gamma,\Sigma_k) + I_2(\gamma_2,\Sigma_k) + I_2(\check{\gamma},\Sigma_k) + I_2(\gamma_1,\Sigma_k)=1\mod 2.
\end{align}
On the other hand, from the assumption that $M$ is simply connected, $\tilde\gamma$ is homotopic equivalent to a constant curve at $q_1$. The mod 2 intersection number is invariant under the homotopic equivalence. So
\begin{align}
   I_2(\tilde\gamma,\Sigma_k) = I_2(q_1,\Sigma_k)=0 \mod 2,
\end{align}
which is a contradiction.

