\label{lem det of positive semi definite matrix}
    Let $X, Y$ be two positive semi-definite $(n\times n)$-matrices, then
    \begin{align*}
        \det(X+Y)\geq \det(X)+\det(Y).
    \end{align*}

\begin{align*}
        \det(X+Y)\geq \det(X)+\det(Y).
    \end{align*}

 The inequality is trivial when $\det(X)+\det(Y)=0$. Without loss of generality,  we assume $\det(X)>0$ in the following proof.
\begin{align*}
    \det(X+Y)=&\det(\sqrt{X}(I+\sqrt{X}^{-1}Y\sqrt{X}^{-1})\sqrt{X})=\det(X)\det(I+\sqrt{X}^{-1}Y\sqrt{X}^{-1}).
\end{align*}
Let $\lambda_i\geq 0$ be the eigenvalues of $\sqrt{X}^{-1}Y\sqrt{X}^{-1}$, then 
\begin{align*}
    \det(I+\sqrt{X}^{-1}Y\sqrt{X}^{-1})=& \prod_{i=1}^n(1+\lambda_i)\geq1+\prod_{i=1}^n\lambda_i\\
    =& 1+\det(\sqrt{X}^{-1}Y\sqrt{X}^{-1})=1+\det(Y)\det(X)^{-1}.
\end{align*}
We complete the proof.

\begin{align*}
