    \end{align*}
where $\bracket{\cdot,  \cdot}_q$ is the inner product with respect to the metric on $T_{q}M$ and $q= \varphi(\theta)$.

Note
    \begin{align*}
        \frac{\partial \varphi(\theta)}{\partial \theta^i}=&\mathrm{d}\exp_p\big(r(\theta)\theta\big)\left(\frac{\partial \big(r(\theta)\theta\big)}{\partial \theta^i}\right) =\mathrm{d}\exp_p\big(r(\theta)\theta\big)\bigg(\frac{\partial r(\theta)}{\partial \theta^i}\theta + r(\theta)\frac{\partial\theta}{\partial \theta^i}\bigg)\\
        =&\frac{\partial r(\theta)}{\partial \theta^i}\mathrm{d}\exp_p\big(r(\theta)\theta\big)(\theta) + r(\theta)\mathrm{d}\exp_p\big(r(\theta)\theta\big)\bigg(\frac{\partial\theta}{\partial \theta^i}\bigg).
    \end{align*} 

