        \bracket{A,B_i}_q=&r(\theta)\bracket{\mathrm{d}\exp_p\big(r(\theta)\theta\big)(\theta),\mathrm{d}\exp_p(r(\theta)\theta)\left(\frac{\partial \theta}{\partial \theta^i}\right)}_q        =r(\theta)\bracket{\theta,\frac{\partial \theta}{\partial \theta^i}}_p=0.
    \end{align*}

 From the above we get 
