If $(M^n, g)$ has $Rc\geq 0$ and only one end,   suppose $\Sigma \subset  N_{k- 1}$ is a smooth, compact hypersurface separating $\partial E_{k- 1}$ from $\partial E_{k}$, then
\begin{align}
V\Big((\partial B_p(s)\cap N_k)- \mathrm{Cut}(p)\Big)\leq (\frac{s}{(k- 1)L})^{n- 1}\cdot V(\Sigma), \quad \quad \forall s> kL. \nonumber 
\end{align}

\begin{align}
V\Big((\partial B_p(s)\cap N_k)- \mathrm{Cut}(p)\Big)\leq (\frac{s}{(k- 1)L})^{n- 1}\cdot V(\Sigma), \quad \quad \forall s> kL. \nonumber 
\end{align}

 Let $\tilde{\Sigma}\vcentcolon= \Sigma-\mathrm{Cut}(p)$, define $\Pi:\tilde{\Sigma}\to \mathbb{S}_p(M)$ as $\displaystyle \Pi(q)=\frac{\exp_p^{-1}(q)}{|\exp_p^{-1}(q)|_{g(p)}}$,  where $\mathbb{S}_pM$ is the unit tangent space of $M$ at $p$. From the definition of cut points,  the map $\Pi$ is a well-defined smooth map.

From the separating property of $\Sigma$, we know that 
\begin{align}
\Theta_{k}\vcentcolon=\frac{1}{s}\exp_p^{-1}\big((\partial B_p(s)\cap N_k)-\mathrm{Cut}(p)\big)\subseteq \Pi(\tilde{\Sigma}). \nonumber 
\end{align}
Applying Sard's theorem on the map $\Pi:\tilde{\Sigma}\to \mathbb{S}_p(M)$, we obtain that the set of critical values of $\Pi$ (denoted as $\mathcal{C}(\Pi)$) satisfies $\mathcal{H}^{n- 1}(\mathcal{C}(\Pi))= 0$, where $\mathcal{H}^{n- 1}$ is $(n- 1)$-dim Hausdorff measure on $\mathbb{S}_pM$.

Define
\begin{align}
\Theta_{k}'= \Theta_{k}- \mathcal{C}(\Pi). \label{0 diff between sets}
\end{align}
Let $\Sigma'\subset (\tilde\Sigma\cap\Pi^{-1}(\Theta_{k}))$ be the regular points of $\Pi$ with image in $\Theta_{k}$. Then $\Sigma'$ is an open subset of ${\bf\mathbb S}_p M$ from the implicit function theorem, and 
\begin{align}
\Theta_{k}'\subset\Pi(\Sigma'). \nonumber 
\end{align}

For any $q_0\in\Sigma'$, there is a local coordinate chart $(U,h)$ of $\Sigma'$ containing $q_0$, such that $\Pi|_{U}$ is a diffeomorphism between $U$ and $\Pi(U)$. And 
\begin{align}
\varphi(\theta)\vcentcolon=\exp_p(r(\theta)\cdot \theta)= (\Pi\big|_U)^{-1}(\theta), \nonumber 
\end{align}
is a smooth function defined on $\Pi(U)\subseteq \mathbb{S}_pM$. 

For any $\theta\in \Theta_{k}'$, note $(k- 1)L\leq r(\theta)\leq kL< s$. From Lemma \ref{lem volume of surface in term of polar Jac} and Bishop-Gromov's volume comparison Theorem, we get
\begin{align}
    J_{(\Pi\big|_U)^{-1}}(\theta)&= J_\varphi(\theta) \geq J(r(\theta),\theta) \geq \bigg(\frac{r(\theta)}{s}\bigg)^{n- 1}J(s,\theta) \geq \bigg(\frac{(k- 1)L}{s}\bigg)^{n- 1}J(s,\theta). \nonumber 
\end{align}

Finally by the area formula, (\ref{0 diff between sets}) and $\mathcal{H}^{n- 1}(\mathcal{C}(\Pi))= 0$, we get
