    V(\Sigma)\geq & V(\Sigma')\geq V(\Pi^{-1}(\Theta_{k}'))
    \geq \bigg(\frac{(k- 1)L}{s}\bigg)^{n- 1}\int_{\Theta_{k}'} J(s,\theta)\mathrm{d} \mathcal{H}^{{n- 1}}(\theta)\\
    &=\bigg(\frac{(k- 1)L}{s}\bigg)^{n- 1}\int_{\Theta_{k}} J(s,\theta)\mathrm{d} \mathcal{H}^{{n- 1}}(\theta)\\
&=\bigg(\frac{(k- 1)L}{s}\bigg)^{n- 1} V\Big((\partial B_p(s)\cap N_k)- \mathrm{Cut}(p)\Big).
\end{align*}

